package com.mfg.erp.service;import com.mfg.common.api.*;import com.mfg.common.integration.BusinessEventService;import com.mfg.workflow.dto.StartApprovalRequest;import com.mfg.workflow.entity.WfInstance;import com.mfg.workflow.service.ApprovalEngine;import com.mfg.common.exception.BizException;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.sql.Date;import java.time.LocalDate;import java.util.*;
@Service @RequiredArgsConstructor public class ErpP2Service{private final JdbcTemplate db;private final ApprovalEngine workflow;private final BusinessEventService events;private int pn(int p){return Math.max(0,p-1);}private int ps(int s){return Math.min(200,Math.max(1,s));}
 public Page<Map<String,Object>> list(String table,String keyword,String status,int page,int size){if(!Set.of("erp_customer_credit","erp_mrp_run","erp_plan_suggestion","erp_receivable","erp_invoice","erp_receipt","erp_payable","erp_prod_order").contains(table))throw BizException.of(ErrorCode.PARAM_INVALID,"不支持的业务对象");String k=keyword==null?"":keyword,st=status==null?"":status,statusCol=table.equals("erp_prod_order")?"order_status":table.equals("erp_receivable")?"settle_status":"status";String where=" WHERE (?='' OR CONCAT_WS(' ',"+switch(table){case"erp_customer_credit"->"customer_code,risk_level";case"erp_mrp_run"->"run_no,sales_order_no";case"erp_plan_suggestion"->"suggestion_no,material_code,source_sales_order_no";case"erp_receivable"->"receivable_no,customer_code,sales_order_no";case"erp_invoice"->"invoice_no,customer_code,sales_order_no";case"erp_receipt"->"receipt_no,customer_code,bank_reference";case"erp_payable"->"payable_no,supplier_code,source_order_no";default->"prod_order_no,sales_order_no,product_code";}+") LIKE ?) AND (?='' OR "+statusCol+"=?)";Object[]a={k,"%"+k+"%",st,st};long total=db.queryForObject("SELECT COUNT(*) FROM src_erp."+table+where,Long.class,a);return new PageImpl<>(db.queryForList("SELECT * FROM src_erp."+table+where+" ORDER BY id DESC LIMIT ? OFFSET ?",add(a,ps(size),pn(page)*ps(size))),PageRequest.of(pn(page),ps(size)),total);}
 @Transactional public Map<String,Object> credit(long orderId){Map<String,Object>o=one("erp_sales_order","id",orderId);String customer=String.valueOf(o.get("customer_code"));List<Map<String,Object>>cs=db.queryForList("SELECT * FROM src_erp.erp_customer_credit WHERE customer_code=?",customer);if(cs.isEmpty()){Map<String,Object>md=db.queryForMap("SELECT credit_limit,credit_used FROM src_mdm.md_customer WHERE customer_code=?",customer);db.update("INSERT INTO src_erp.erp_customer_credit(customer_code,credit_limit,used_amount) VALUES(?,?,?)",customer,md.get("credit_limit"),md.get("credit_used"));cs=db.queryForList("SELECT * FROM src_erp.erp_customer_credit WHERE customer_code=?",customer);}Map<String,Object>c=cs.get(0);BigDecimal limit=bd(c.get("credit_limit")),used=bd(c.get("used_amount")),overdue=bd(c.get("overdue_amount")),amount=bd(o.get("total_amount")),available=limit.subtract(used);String result=available.compareTo(amount)>=0&&overdue.signum()==0&&!"HIGH".equals(c.get("risk_level"))?"PASSED":"EXCEPTION";db.update("INSERT INTO src_erp.erp_credit_check(sales_order_no,customer_code,order_amount,available_credit,overdue_amount,risk_level,result) VALUES(?,?,?,?,?,?,?)",o.get("sales_order_no"),customer,amount,available,overdue,c.get("risk_level"),result);db.update("UPDATE src_erp.erp_sales_order SET credit_status=?,order_status=? WHERE id=?",result,result.equals("PASSED")?"CREDIT_PASSED":"CREDIT_EXCEPTION",orderId);return db.queryForMap("SELECT * FROM src_erp.erp_credit_check WHERE sales_order_no=? ORDER BY id DESC LIMIT 1",o.get("sales_order_no"));}
 @Transactional public WfInstance submitCreditException(long orderId,String reason){if(reason==null||reason.isBlank())throw BizException.of(ErrorCode.PARAM_INVALID,"信用例外原因必填");Map<String,Object>o=one("erp_sales_order","id",orderId);Map<String,Object>check=db.queryForMap("SELECT * FROM src_erp.erp_credit_check WHERE sales_order_no=? ORDER BY id DESC LIMIT 1",o.get("sales_order_no"));if(!"EXCEPTION".equals(check.get("result")))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"当前信用检查不需要例外审批");db.update("UPDATE src_erp.erp_credit_check SET exception_reason=?,exception_status='PENDING' WHERE id=?",reason,check.get("id"));return workflow.start(StartApprovalRequest.of("CREDIT_EXCEPTION",((Number)check.get("id")).longValue(),String.valueOf(o.get("sales_order_no")),"客户信用例外审批"));}
 @Transactional public void creditApproval(long checkId,boolean approved){Map<String,Object>check=one("erp_credit_check","id",checkId);db.update("UPDATE src_erp.erp_credit_check SET exception_status=?,result=? WHERE id=?",approved?"APPROVED":"REJECTED",approved?"PASSED":"EXCEPTION",checkId);db.update("UPDATE src_erp.erp_sales_order SET credit_status=?,order_status=? WHERE sales_order_no=?",approved?"PASSED":"EXCEPTION",approved?"CREDIT_PASSED":"CREDIT_EXCEPTION",check.get("sales_order_no"));}
 @Transactional public List<Map<String,Object>> atp(long orderId){Map<String,Object>o=one("erp_sales_order","id",orderId);if(!"PASSED".equals(o.get("credit_status")))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"必须先通过信用检查");String no=String.valueOf(o.get("sales_order_no")),factory=String.valueOf(o.getOrDefault("factory_code","F001"));db.update("DELETE FROM src_erp.erp_atp_snapshot WHERE sales_order_no=?",no);for(Map<String,Object>l:db.queryForList("SELECT * FROM src_erp.erp_sales_order_line WHERE sales_order_no=?",no)){BigDecimal safe=queryBd("SELECT safety_stock FROM src_mdm.md_material WHERE material_code=?",l.get("material_code")),available=queryBd("SELECT COALESCE(SUM(available_stock+confirmed_purchase+planned_production-allocated_demand),0) FROM src_erp.erp_supply_snapshot WHERE material_code=? AND factory_code=?",l.get("material_code"),factory).subtract(safe),need=bd(l.get("order_qty"));BigDecimal promise=available.max(BigDecimal.ZERO).min(need);String result=promise.compareTo(need)>=0?"FULL":"PARTIAL";LocalDate promised=result.equals("FULL")?LocalDate.now():LocalDate.now().plusDays(14);db.update("INSERT INTO src_erp.erp_atp_snapshot(sales_order_no,line_no,material_code,requested_qty,available_qty,promised_qty,promised_date,result,basis_json) VALUES(?,?,?,?,?,?,?,?,JSON_OBJECT('安全库存',?,'工厂',?))",no,l.get("line_no"),l.get("material_code"),need,available,promise,Date.valueOf(promised),result,safe,factory);}List<Map<String,Object>>r=db.queryForList("SELECT * FROM src_erp.erp_atp_snapshot WHERE sales_order_no=?",no);db.update("UPDATE src_erp.erp_sales_order SET atp_status=?,order_status=? WHERE id=?",r.stream().allMatch(x->"FULL".equals(x.get("result")))?"COMMITTED":"PARTIAL","ATP_COMMITTED",orderId);return r;}
 @Transactional public void confirm(long id){Map<String,Object>o=one("erp_sales_order","id",id);if(!"PASSED".equals(o.get("credit_status"))||!Set.of("COMMITTED","PARTIAL").contains(o.get("atp_status")))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"订单必须完成信用检查和交期承诺");db.update("UPDATE src_erp.erp_sales_order SET order_status='CONFIRMED' WHERE id=?",id);db.update("UPDATE src_erp.erp_customer_credit SET used_amount=used_amount+? WHERE customer_code=?",o.get("total_amount"),o.get("customer_code"));events.publish("ERP.SALES_ORDER.CONFIRMED","erp","crm","SALES_ORDER",o.get("sales_order_no"),Map.of("customerCode",String.valueOf(o.get("customer_code")),"amount",o.get("total_amount")));}
 @Transactional public void change(long id,Map<String,Object>x){Map<String,Object>o=one("erp_sales_order","id",id);if(!Set.of("DRAFT","CONFIRMED","ATP_COMMITTED").contains(o.get("order_status")))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"当前状态不能变更");String reason=s(x,"reason",null);if(reason==null)throw BizException.of(ErrorCode.PARAM_INVALID,"变更原因必填");db.update("INSERT INTO src_erp.erp_sales_order_change(sales_order_id,change_type,reason,before_json,operator) VALUES(?,'CHANGE',?,JSON_OBJECT('交期',?,'金额',?),?)",id,reason,o.get("delivery_date"),o.get("total_amount"),CurrentUser.usernameOrSystem());db.update("UPDATE src_erp.erp_sales_order SET delivery_date=COALESCE(?,delivery_date),remark=COALESCE(?,remark),credit_status='UNCHECKED',atp_status='UNCHECKED',order_status='DRAFT' WHERE id=?",date(x,"deliveryDate"),s(x,"remark",null),id);}
 @Transactional public void cancel(long id,String reason){Map<String,Object>o=one("erp_sales_order","id",id);if(Set.of("CLOSED","CANCELED").contains(o.get("order_status")))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"订单已结束");if(reason==null||reason.isBlank())throw BizException.of(ErrorCode.PARAM_INVALID,"取消原因必填");db.update("INSERT INTO src_erp.erp_sales_order_change(sales_order_id,change_type,reason,operator) VALUES(?,'CANCEL',?,?)",id,reason,CurrentUser.usernameOrSystem());db.update("UPDATE src_erp.erp_sales_order SET order_status='CANCELED' WHERE id=?",id);}
 @Transactional public List<Map<String,Object>> acceptAtp(long orderId,String reason){Map<String,Object>o=one("erp_sales_order","id",orderId);List<Map<String,Object>>rows=db.queryForList("SELECT * FROM src_erp.erp_atp_snapshot WHERE sales_order_no=?",o.get("sales_order_no"));if(rows.isEmpty())throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"请先执行ATP计算");boolean partial=rows.stream().anyMatch(x->"PARTIAL".equals(x.get("result")));if(partial&&(reason==null||reason.isBlank()))throw BizException.of(ErrorCode.PARAM_INVALID,"分批交付必须填写例外原因");db.update("UPDATE src_erp.erp_atp_snapshot SET accepted=1,exception_reason=?,exception_status=? WHERE sales_order_no=?",reason,partial?"APPROVED":"NOT_REQUIRED",o.get("sales_order_no"));db.update("UPDATE src_erp.erp_sales_order SET atp_status='COMMITTED',order_status='ATP_COMMITTED' WHERE id=?",orderId);return db.queryForList("SELECT * FROM src_erp.erp_atp_snapshot WHERE sales_order_no=?",o.get("sales_order_no"));}
 @Transactional public Map<String,Object> createMrp(Map<String,Object>x){String no=s(x,"runNo","MRP-"+System.currentTimeMillis());db.update("INSERT INTO src_erp.erp_mrp_run(run_no,run_type,sales_order_no,factory_code,plan_date,status,created_by) VALUES(?,?,?,?,?,'CREATED',?)",no,s(x,"runType","ORDER"),s(x,"salesOrderNo",null),s(x,"factoryCode","F001"),date(x,"planDate")!=null?date(x,"planDate"):Date.valueOf(LocalDate.now()),CurrentUser.usernameOrSystem());return one("erp_mrp_run","run_no",no);}
 @Transactional public Map<String,Object> executeMrp(long runId){Map<String,Object>run=one("erp_mrp_run","id",runId);if(!"CREATED".equals(run.get("status")))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"计划运行已经执行");db.update("UPDATE src_erp.erp_mrp_run SET status='RUNNING',started_at=NOW(3) WHERE id=?",runId);String so=String.valueOf(run.get("sales_order_no"));for(Map<String,Object>line:db.queryForList("SELECT * FROM src_erp.erp_sales_order_line WHERE sales_order_no=?",so))explode(runId,so,String.valueOf(line.get("material_code")),bd(line.get("order_qty")),0,Date.valueOf(String.valueOf(line.get("delivery_date"))));db.update("UPDATE src_erp.erp_mrp_run SET status='COMPLETED',finished_at=NOW(3) WHERE id=?",runId);events.publish("ERP.MRP.COMPLETED","erp","crm","MRP_RUN",runId,Map.of("runNo",String.valueOf(run.get("run_no")),"salesOrderNo",so));return one("erp_mrp_run","id",runId);}
 private void explode(long runId,String so,String material,BigDecimal qty,int level,Date needDate){List<Map<String,Object>>bom=db.queryForList("SELECT b.bom_code,b.bom_version,b.base_qty,l.child_material_code,l.qty_per,l.scrap_rate FROM src_erp.erp_md_bom b JOIN src_erp.erp_md_bom_line l ON l.bom_code=b.bom_code AND l.bom_version=b.bom_version WHERE b.product_code=? AND b.is_current=1",material);if(bom.isEmpty()){planRequirement(runId,so,null,material,qty,level,needDate);return;}for(Map<String,Object>b:bom){BigDecimal child=qty.multiply(bd(b.get("qty_per"))).multiply(BigDecimal.ONE.add(bd(b.get("scrap_rate")).divide(BigDecimal.valueOf(100),6,RoundingMode.HALF_UP))).divide(bd(b.get("base_qty")),6,RoundingMode.HALF_UP);planRequirement(runId,so,material,String.valueOf(b.get("child_material_code")),child,level+1,needDate);explode(runId,so,String.valueOf(b.get("child_material_code")),child,level+1,needDate);}}
 private void planRequirement(long runId,String so,String parent,String material,BigDecimal gross,int level,Date date){Map<String,Object>m=db.queryForMap("SELECT material_type,base_unit_code,safety_stock FROM src_mdm.md_material WHERE material_code=?",material);BigDecimal available=queryBd("SELECT COALESCE(SUM(available_stock+confirmed_purchase+planned_production-allocated_demand),0) FROM src_erp.erp_supply_snapshot WHERE material_code=?",material),safe=bd(m.get("safety_stock")),net=gross.add(safe).subtract(available).max(BigDecimal.ZERO);db.update("INSERT INTO src_erp.erp_mrp_requirement(run_id,parent_material_code,material_code,material_type,level_no,gross_requirement,available_qty,safety_stock,net_requirement,required_date,shortage_flag) VALUES(?,?,?,?,?,?,?,?,?,?,?)",runId,parent,material,m.get("material_type"),level,gross,available,safe,net,date,net.signum()>0);if(net.signum()>0){String type=Set.of("FINISHED","SEMI").contains(m.get("material_type"))?"PRODUCTION":"PURCHASE",no=(type.equals("PRODUCTION")?"PS-":"PR-")+System.nanoTime();db.update("INSERT INTO src_erp.erp_plan_suggestion(run_id,suggestion_no,suggestion_type,material_code,quantity,unit_code,required_date,source_sales_order_no) VALUES(?,?,?,?,?,?,?,?)",runId,no,type,material,net,m.get("base_unit_code"),date,so);}}
 @Transactional public Map<String,Object> confirmSuggestion(long id){Map<String,Object>s=one("erp_plan_suggestion","id",id);if(!"PROPOSED".equals(s.get("status")))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"建议已处理");String no;if("PURCHASE".equals(s.get("suggestion_type"))){no="PR-"+System.currentTimeMillis();db.update("INSERT INTO src_erp.erp_purchase_requisition(requisition_no,source_suggestion_no,material_code,quantity,required_date) VALUES(?,?,?,?,?)",no,s.get("suggestion_no"),s.get("material_code"),s.get("quantity"),s.get("required_date"));}else{no="MO-"+System.currentTimeMillis();List<Map<String,Object>>versions=db.queryForList("SELECT * FROM src_mdm.md_production_version WHERE product_code=? AND status='PUBLISHED' AND effective_date<=CURRENT_DATE AND (expire_date IS NULL OR expire_date>=CURRENT_DATE) ORDER BY version_no DESC LIMIT 1",s.get("material_code"));if(versions.isEmpty())throw BizException.of(ErrorCode.MASTER_DATA_NOT_PUBLISHED,"该产品没有已发布且有效的生产版本");Map<String,Object>v=versions.get(0);db.update("INSERT INTO src_erp.erp_prod_order(prod_order_no,sales_order_no,product_code,plan_qty,unit_code,plan_start_date,plan_finish_date,bom_code,bom_version,routing_code,routing_version,factory_code,production_version_code,order_status,created_by) VALUES(?,?,?,?,?,CURRENT_DATE,?,?,?,?,?,?,?,?,?)",no,s.get("source_sales_order_no"),s.get("material_code"),s.get("quantity"),s.get("unit_code"),s.get("required_date"),v.get("bom_code"),v.get("bom_version"),v.get("routing_code"),v.get("routing_version"),v.get("factory_code"),v.get("production_version_code"),"CREATED",CurrentUser.usernameOrSystem());}db.update("UPDATE src_erp.erp_plan_suggestion SET status='CONFIRMED',converted_order_no=? WHERE id=?",no,id);String eventType="PURCHASE".equals(s.get("suggestion_type"))?"ERP.PURCHASE_REQUISITION.CREATED":"ERP.PRODUCTION_ORDER.CREATED";String target="PURCHASE".equals(s.get("suggestion_type"))?"srm":"mes";events.publish(eventType,"erp",target,"PLAN_SUGGESTION",id,Map.of("suggestionNo",String.valueOf(s.get("suggestion_no")),"convertedOrderNo",no));return one("erp_plan_suggestion","id",id);}
 public Map<String,Object> kitCheck(long id){Map<String,Object>o=one("erp_prod_order","id",id);List<Map<String,Object>>r=db.queryForList("SELECT l.child_material_code,l.qty_per*?*(1+l.scrap_rate/100) required_qty,COALESCE(s.available_stock,0) available_qty FROM src_erp.erp_md_bom_line l LEFT JOIN src_erp.erp_supply_snapshot s ON s.material_code=l.child_material_code WHERE l.bom_code=? AND l.bom_version=?",o.get("plan_qty"),o.get("bom_code"),o.get("bom_version"));boolean ready=r.stream().allMatch(x->bd(x.get("available_qty")).compareTo(bd(x.get("required_qty")))>=0);db.update("UPDATE src_erp.erp_prod_order SET kit_status=?,kit_checked_at=NOW(3) WHERE id=?",ready?"READY":"SHORTAGE",id);return Map.of("ready",ready,"items",r);}
 @Transactional public Map<String,Object> invoice(Map<String,Object>x){String no=s(x,"invoiceNo","INV-"+System.currentTimeMillis());String so=s(x,"salesOrderNo",null);Map<String,Object>o=db.queryForMap("SELECT * FROM src_erp.erp_sales_order WHERE sales_order_no=?",so);BigDecimal amount=d(x,"amount");db.update("INSERT INTO src_erp.erp_invoice(invoice_no,sales_order_no,customer_code,invoice_date,amount,tax_amount,status,created_by) VALUES(?,?,?,CURRENT_DATE,?,?,'ISSUED',?)",no,so,o.get("customer_code"),amount,d(x,"taxAmount"),CurrentUser.usernameOrSystem());String voucher=createVoucher("SALES",no,so,amount,"1122","销售开票确认应收");db.update("UPDATE src_erp.erp_invoice SET voucher_no=? WHERE invoice_no=?",voucher,no);String ar="AR-"+System.currentTimeMillis();db.update("INSERT INTO src_erp.erp_receivable(receivable_no,customer_code,customer_name,sales_order_no,invoice_no,invoice_date,due_date,invoice_amount,received_amount,outstanding_amount,settle_status,created_by) VALUES(?,?,?,?,?,CURRENT_DATE,DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY),?,0,?,'OPEN',?)",ar,o.get("customer_code"),o.get("customer_name"),so,no,amount,amount,CurrentUser.usernameOrSystem());return one("erp_invoice","invoice_no",no);}
 @Transactional public Map<String,Object> receipt(Map<String,Object>x){String no=s(x,"receiptNo","RC-"+System.currentTimeMillis());BigDecimal amount=d(x,"amount");db.update("INSERT INTO src_erp.erp_receipt(receipt_no,customer_code,bank_reference,receipt_date,amount,unapplied_amount,status,created_by) VALUES(?,?,?,?,?,?,'UNAPPLIED',?)",no,s(x,"customerCode",null),s(x,"bankReference",null),date(x,"receiptDate")!=null?date(x,"receiptDate"):Date.valueOf(LocalDate.now()),amount,amount,CurrentUser.usernameOrSystem());String voucher=createVoucher("RECEIPT",no,null,amount,"1002","客户回款");db.update("UPDATE src_erp.erp_receipt SET voucher_no=? WHERE receipt_no=?",voucher,no);return one("erp_receipt","receipt_no",no);}
 @Transactional public void settle(Map<String,Object>x){long receiptId=l(x,"receiptId"),arId=l(x,"receivableId");BigDecimal amount=d(x,"amount");Map<String,Object>r=one("erp_receipt","id",receiptId),ar=one("erp_receivable","id",arId);if(amount.signum()<=0||amount.compareTo(bd(r.get("unapplied_amount")))>0||amount.compareTo(bd(ar.get("outstanding_amount")))>0)throw BizException.of(ErrorCode.PARAM_INVALID,"核销金额超过可用余额");String no=s(x,"settlementNo","ST-"+System.currentTimeMillis());db.update("INSERT INTO src_erp.erp_settlement(settlement_no,receipt_id,receivable_id,amount,settled_by) VALUES(?,?,?,?,?)",no,receiptId,arId,amount,CurrentUser.usernameOrSystem());db.update("UPDATE src_erp.erp_receipt SET unapplied_amount=unapplied_amount-?,status=IF(unapplied_amount-?=0,'APPLIED','PARTIAL') WHERE id=?",amount,amount,receiptId);db.update("UPDATE src_erp.erp_receivable SET received_amount=received_amount+?,outstanding_amount=outstanding_amount-?,settled_amount=settled_amount+?,settle_status=IF(outstanding_amount-?=0,'SETTLED','PARTIAL'),status=IF(outstanding_amount-?=0,'SETTLED','PARTIAL') WHERE id=?",amount,amount,amount,amount,amount,arId);db.update("UPDATE src_erp.erp_customer_credit SET used_amount=GREATEST(0,used_amount-?) WHERE customer_code=?",amount,ar.get("customer_code"));String voucher=createVoucher("SETTLEMENT",no,String.valueOf(ar.get("sales_order_no")),amount,"1122","回款核销应收");db.update("UPDATE src_erp.erp_settlement SET voucher_no=? WHERE settlement_no=?",voucher,no);events.publish("ERP.RECEIPT.SETTLED","erp","crm","SETTLEMENT",no,Map.of("salesOrderNo",String.valueOf(ar.get("sales_order_no")),"amount",amount));}
 @Transactional public Map<String,Object> createPayable(Map<String,Object>x){String no=s(x,"payableNo","AP-"+System.currentTimeMillis());BigDecimal amount=d(x,"amount");if(amount.signum()<=0)throw BizException.of(ErrorCode.PARAM_INVALID,"应付金额必须大于0");db.update("INSERT INTO src_erp.erp_payable(payable_no,supplier_code,source_order_no,amount,paid_amount,due_date,status) VALUES(?,?,?,?,0,?,'OPEN')",no,s(x,"supplierCode",null),s(x,"sourceOrderNo",null),amount,date(x,"dueDate"));return one("erp_payable","payable_no",no);}
 private String createVoucher(String sourceType,String sourceNo,String salesOrderNo,BigDecimal amount,String subject,String summary){String no="V-"+System.currentTimeMillis()+"-"+Math.abs(sourceNo.hashCode()%1000);String period=LocalDate.now().toString().substring(0,7);db.update("INSERT INTO src_erp.erp_fin_voucher(voucher_no,company_code,fiscal_period,voucher_date,debit_amount,credit_amount,subject_code,source_type,source_no,sales_order_no,summary,created_by) VALUES(?,'C001',?,CURRENT_DATE,?,?,?,?,?,?,?,?,?)",no,period,amount,amount,subject,sourceType,sourceNo,salesOrderNo,summary,CurrentUser.usernameOrSystem());return no;}
 public Map<String,Object> margin(String so){Map<String,Object>o=db.queryForMap("SELECT sales_order_no,total_amount revenue FROM src_erp.erp_sales_order WHERE sales_order_no=?",so);BigDecimal cost=queryBd("SELECT COALESCE(SUM(amount),0) FROM src_erp.erp_order_cost WHERE sales_order_no=?",so),revenue=bd(o.get("revenue")),margin=revenue.subtract(cost);return Map.of("salesOrderNo",so,"revenue",revenue,"cost",cost,"grossMargin",margin,"grossMarginRate",revenue.signum()==0?BigDecimal.ZERO:margin.divide(revenue,6,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100)));}
 private Map<String,Object>one(String t,String c,Object v){List<Map<String,Object>>r=db.queryForList("SELECT * FROM src_erp."+t+" WHERE "+c+"=?",v);if(r.isEmpty())throw BizException.of(ErrorCode.MASTER_DATA_NOT_FOUND,"业务数据不存在");return r.get(0);}private BigDecimal queryBd(String sql,Object...a){BigDecimal v=db.queryForObject(sql,BigDecimal.class,a);return v==null?BigDecimal.ZERO:v;}private BigDecimal bd(Object v){return v==null?BigDecimal.ZERO:new BigDecimal(String.valueOf(v));}private Object[]add(Object[]a,Object...b){Object[]r=Arrays.copyOf(a,a.length+b.length);System.arraycopy(b,0,r,a.length,b.length);return r;}private String s(Map<String,Object>x,String k,String z){Object v=x.get(k);return v==null||String.valueOf(v).isBlank()?z:String.valueOf(v);}private Long l(Map<String,Object>x,String k){return Long.valueOf(String.valueOf(x.get(k)));}private BigDecimal d(Map<String,Object>x,String k){return bd(x.get(k));}private Date date(Map<String,Object>x,String k){return x.get(k)==null||String.valueOf(x.get(k)).isBlank()?null:Date.valueOf(String.valueOf(x.get(k)));}
}
